import { IconButton } from '@rmwc/icon-button';
import { MenuItem, SimpleMenu } from '@rmwc/menu';
import { DatabaseReference, ref } from 'firebase/database';
import React, { MutableRefObject, useRef, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { useHistory } from 'react-router-dom';
import { useDatabase } from 'reactfire';

import { DatabaseConfig } from '../../store/config';
import { InteractiveBreadCrumbBar } from '../common/InteractiveBreadCrumbBar';
import { ImportDialog } from './DataViewer/ImportDialog';
import { NodeContainer } from './DataViewer/NodeContainer';
import { useNamespace } from './useNamespace';

export interface PropsFromState {
  path?: string;
  config: DatabaseConfig;
}

export type Props = PropsFromState;

const getPrefix = (ref: DatabaseReference) => {
  const base = ref.root.toString();
  return base.substring(0, base.length - 1);
};

export const Database: React.FC<React.PropsWithChildren<Props>> = ({
  path,
}) => {
  const database = useDatabase();
  const namespace = useNamespace();
  const databaseReference = ref(database, path);
  const history = useHistory();
  const headerMoreOptionsMenuButtonRef =
    useRef() as MutableRefObject<HTMLButtonElement>;

  const [importDialogOpen, setImportDialogOpen] = useState(false);
  const [droppedFile, setDroppedFile] = useState<File | undefined>();

  const closeImportDialog = () => {
    setDroppedFile(undefined);
    setImportDialogOpen(false);
    headerMoreOptionsMenuButtonRef!.current!.focus();
  };

  const urlBase = `/database/${namespace}/data`;
  const handleNavigate = (newPath: string) => {
    if (newPath.startsWith('/')) {
      newPath = newPath.slice(1);
    }
    history.push(`${urlBase}/${newPath}`);
  };

  return (
    <div className="Database-Database">
      {databaseReference ? (
        <>
          <InteractiveBreadCrumbBar
            base={urlBase}
            path={path || '/'}
            inputPrefix={getPrefix(databaseReference)}
            onNavigate={handleNavigate}
          >
            <SimpleMenu
              onSelect={(evt) => {
                switch (evt.detail?.item?.dataset?.value) {
                  case 'IMPORT_JSON':
                    setImportDialogOpen(true);
                    return;
                  default:
                }
              }}
              handle={
                <IconButton
                  icon="more_vert"
                  label="Open menu"
                  ref={headerMoreOptionsMenuButtonRef}
                />
              }
              renderToPortal
            >
              <MenuItem data-value="IMPORT_JSON">Import JSON</MenuItem>
            </SimpleMenu>
          </InteractiveBreadCrumbBar>

          <DatabaseDropZone onDrop={(f) => setDroppedFile(f)}>
            <NodeContainer realtimeRef={databaseReference} isViewRoot />
          </DatabaseDropZone>

          {(importDialogOpen || droppedFile) && (
            <ImportDialog
              reference={databaseReference}
              droppedFile={droppedFile}
              onComplete={closeImportDialog}
            />
          )}
        </>
      ) : (
        <p>Loading</p>
      )}
    </div>
  );
};

export default Database;

/**
 * Renders child content inside a dropzone that will show a scrim and accept
 * JSON files
 */
const DatabaseDropZone: React.FC<
  React.PropsWithChildren<{ onDrop: (file: File) => void }>
> = ({ onDrop, children }) => {
  const { getInputProps, getRootProps, isDragActive, isDragAccept } =
    useDropzone({
      onDrop: (files) => onDrop(files[0]),
      noClick: true,
      accept: {
        'application/json': ['.json'],
      },
    });

  return (
    <div className="Database-Content" {...getRootProps()}>
      {children}

      {isDragActive && (
        <div className="Database-Content-Dragging">
          {isDragAccept ? (
            'Drop JSON file to import'
          ) : (
            <span className="invalid">
              Only JSON files are supported for data import.
            </span>
          )}
        </div>
      )}

      <input {...getInputProps()} />
    </div>
  );
};
